#pragma once
#define KOTATSU_CONCAT_IMPL(a, b) a##b
#define KOTATSU_CONCAT(a, b) KOTATSU_CONCAT_IMPL(a, b)
#define KOTATSU_ANNOTATION_ATTRIBUTES(...)                                                             [] {                                                                                                   using ::kotatsu::codec::dsl::rename;                                                               using ::kotatsu::codec::dsl::description;                                                          using ::kotatsu::codec::dsl::alias;                                                                using ::kotatsu::codec::dsl::skip;                                                                 using ::kotatsu::codec::dsl::flatten;                                                              using ::kotatsu::codec::dsl::presence;                                                             using ::kotatsu::codec::dsl::as;                                                                   using ::kotatsu::codec::dsl::with;                                                                 using ::kotatsu::codec::dsl::schema_default;                                                       using ::kotatsu::codec::dsl::minimum;                                                              using ::kotatsu::codec::dsl::maximum;                                                              using ::kotatsu::codec::dsl::choices;                                                              using ::kotatsu::codec::dsl::rename_all;                                                           using ::kotatsu::codec::dsl::deny_unknown_fields;                                                  using ::kotatsu::codec::dsl::presence_all;                                                         using ::kotatsu::codec::dsl::tagged;                                                               using ::kotatsu::codec::dsl::tag;                                                                  using ::kotatsu::codec::dsl::content;                                                              using ::kotatsu::codec::dsl::tag_names;                                                            using ::kotatsu::meta::dsl::type;                                                                  using enum ::kotatsu::codec::presence_kind;                                                        using ::kotatsu::naming::Casing;                                                                   return ::kotatsu::meta::make_annotation(__VA_ARGS__);                                          }()
#define KANNOTATION(name, ...)                                                                         [[maybe_unused]] constexpr inline auto name = KOTATSU_ANNOTATION_ATTRIBUTES(__VA_ARGS__)
#define KANNOTATE(member, ...)                                                                         [[maybe_unused]] static consteval auto __kotatsu__annotation(                                          ::kotatsu::meta::detail::member_key_t<#member>) {                                                  [[maybe_unused]] ::std::type_identity<decltype(::kotatsu::meta::detail::member_probe {             } member)> annotated;                                                                              return KOTATSU_ANNOTATION_ATTRIBUTES(__VA_ARGS__);                                             }
#define KOTATSU_CLASS_KEY_struct ~, 1,
#define KOTATSU_CLASS_KEY_class ~, 1,
#define KOTATSU_SECOND_IMPL(first, second, ...) second
#define KOTATSU_SECOND(...) KOTATSU_SECOND_IMPL(__VA_ARGS__)
#define KOTATSU_DECLARES(annotated)                                                                    KOTATSU_SECOND(KOTATSU_CONCAT(KOTATSU_CLASS_KEY_, annotated), 0, ~)
#define KOTATSU_WHEN_0(...)
#define KOTATSU_WHEN_1(...) __VA_ARGS__
#define KOTATSU_WHEN(condition) KOTATSU_CONCAT(KOTATSU_WHEN_, condition)
#define KANNOTATE_TYPE(annotated, ...)                                                                 KOTATSU_WHEN(KOTATSU_DECLARES(annotated))(annotated;) [[maybe_unused]] constexpr auto                  __kotatsu__type_annotation(::std::type_identity<annotated>) {                                      return KOTATSU_ANNOTATION_ATTRIBUTES(__VA_ARGS__);                                             }                                                                                                  static_assert(::kotatsu::meta::detail::has_type_annotation<annotated>,                                           "KANNOTATE_TYPE: write it in the namespace of the type it annotates")
#define ZEST_CONCAT_IMPL(a, b) a##b
#define ZEST_CONCAT(a, b) ZEST_CONCAT_IMPL(a, b)
#define ZEST_SUITE(name, ...)                                                                          struct name##TEST;                                                                                 [[maybe_unused]] static const bool zest_registered_##name =                                            ::kotatsu::zest::detail::keep_registered<name##TEST>();                                        struct name##TEST : __VA_OPT__(__VA_ARGS__, )::kotatsu::zest::TestSuiteDef<name##TEST>
#define ZEST_MAKE_ATTRS(...)                                                                           [] constexpr {                                                                                         ::kotatsu::zest::TestAttrs _a{};                                                                   [[maybe_unused]] auto& [skip, focus, serial, crashes] = _a;                                        __VA_ARGS__;                                                                                       return _a;                                                                                     }()
#define ZEST_SUITE_ATTRS(...)                                                                          constexpr static ::kotatsu::zest::TestAttrs suite_attrs = ZEST_MAKE_ATTRS(__VA_ARGS__)
#define ZEST_CASE(name, ...)                                                                           inline static constexpr char _zest_file_##name[] = __FILE__;                                       virtual const void* _register_##name() {                                                               constexpr auto _zest_attrs_ = ZEST_MAKE_ATTRS(__VA_OPT__(__VA_ARGS__));                            return &_register_test_case<&Self::test_##name,                                                                                _zest_file_##name,                                                                                 __LINE__,                                                                                          _zest_attrs_>;                                                     }                                                                                                  void test_##name()
#define ZEST_SPLIT_BEGIN                                                                               _Pragma("clang diagnostic push")                                                                       _Pragma("clang diagnostic ignored \"-Woverloaded-shift-op-parentheses\"")
#define ZEST_SPLIT_END _Pragma("clang diagnostic pop")
#define ZEST_CHECK(checker, ...)                                                                       do {                                                                                                   ZEST_SPLIT_BEGIN                                                                                   ::kotatsu::zest::detail::checker(::kotatsu::zest::detail::Decomposer{} << __VA_ARGS__,                                              #__VA_ARGS__);                                                    ZEST_SPLIT_END                                                                                 } while(0)
#define ZEXPECT(...) ZEST_CHECK(check, __VA_ARGS__)
#define ZASSERT(...) ZEST_CHECK(check_fatal, __VA_ARGS__)
#define ZEST_CONTEXT(...)                                                                              ::kotatsu::zest::Context ZEST_CONCAT(_zest_context_, __COUNTER__) {                                    __VA_ARGS__                                                                                    }
